const books = (g, x, y) => { ['o', 'u', 'h', 'q', 'n', 'c'].forEach((c, i) => g.r(x + 2 + i * 3, y + 4 + (i % 2) * 2, 2, 11 - (i % 2) * 2, c)); g.r(x + 1, y + 15, 16, 1, 'd'); };
